function SalesChart({range,setRange}:{range:string;setRange:(v:string)=>void}){const points="0,142 48,128 96,136 144,97 192,109 240,73 288,84 336,50 384,65 432,28 480,44";return <article className="rounded-3xl border border-app-border/70 bg-white p-5 shadow-sm sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-lg font-bold">Sales analytics</h3><p className="mt-1 text-sm text-zinc-500">Revenue is up <b className="text-green-600">12.5%</b> from last week</p></div><div className="flex rounded-xl bg-app-cream p-1">{["This week","Month","Quarter"].map(x=><button onClick={()=>setRange(x)} key={x} className={`rounded-lg px-3 py-1.5 text-xs font-semibold ${range===x?"bg-white text-app-green shadow-sm":"text-zinc-500"}`}>{x}</button>)}</div></div><div className="relative mt-7 h-56 overflow-hidden"><div className="absolute inset-x-0 top-0 flex h-full flex-col justify-between"><span className="border-b border-dashed border-zinc-200"/><span className="border-b border-dashed border-zinc-200"/><span className="border-b border-dashed border-zinc-200"/><span className="border-b border-dashed border-zinc-200"/></div><svg viewBox="0 0 480 160" preserveAspectRatio="none" className="relative h-[calc(100%-25px)] w-full"><defs><linearGradient id="salesFill" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#f97316" stopOpacity=".25"/><stop offset="1" stopColor="#f97316" stopOpacity="0"/></linearGradient></defs><polygon points={`${points} 480,160 0,160`} fill="url(#salesFill)"/><polyline points={points} fill="none" stroke="#f97316" strokeLinecap="round" strokeLinejoin="round" strokeWidth="3"/></svg><div className="flex justify-between text-[11px] font-medium text-zinc-400"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div></div></article>}
function OrderDonut(){return <article className="rounded-3xl border border-app-border/70 bg-white p-6 shadow-sm"><div className="flex justify-between"><div><h3 className="text-lg font-bold">Order status</h3><p className="text-sm text-zinc-500">1,284 orders this month</p></div><Ellipsis size={18}/></div><div className="relative mx-auto mt-7 grid size-48 place-items-center rounded-full" style={{background:"conic-gradient(#1b3022 0 58%,#f97316 58% 79%,#fbbf24 79% 94%,#fda4af 94% 100%)"}}><div className="grid size-32 place-items-center rounded-full bg-white text-center"><b className="text-3xl">1,284</b><span className="text-xs text-zinc-400">Total orders</span></div></div><div className="mt-6 grid grid-cols-2 gap-y-3 text-sm">{[["Delivered","58%","bg-app-green"],["Out for delivery","21%","bg-app-orange"],["Processing","15%","bg-amber-400"],["Cancelled","6%","bg-rose-300"]].map(([name,value,color])=><div key={name} className="flex items-center gap-2"><i className={`size-2.5 rounded-full ${color}`}/><span className="text-zinc-500">{name}</span><b className="ml-auto mr-4">{value}</b></div>)}</div></article>}
function RecentOrders(){return <article className="overflow-hidden rounded-3xl border border-app-border/70 bg-white shadow-sm"><div className="flex items-center justify-between p-5 sm:p-6"><div><h3 className="text-lg font-bold">Recent orders</h3><p className="text-sm text-zinc-500">Live activity from your storefront</p></div><button className="rounded-xl bg-app-cream px-3 py-2 text-xs font-bold text-app-green">View all orders <ChevronRight className="inline" size={14}/></button></div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="border-y border-app-border/60 bg-app-cream/60 text-[11px] uppercase tracking-wider text-zinc-400"><tr>{["Order","Customer","Items","Payment","Delivery","Amount",""].map(x=><th key={x} className="px-5 py-3">{x}</th>)}</tr></thead><tbody>{orders.map(([id,name,initials,items,payment,delivery,amount])=><tr key={id} className="border-b border-app-border/60 hover:bg-orange-50/40"><td className="px-5 py-4 font-semibold text-app-green">{id}</td><td className="px-5 py-4"><span className="flex items-center gap-2"><i className="grid size-8 place-items-center rounded-full bg-gradient-to-br from-lime-200 to-orange-200 text-[10px] font-bold">{initials}</i>{name}</span></td><td className="px-5 py-4 text-zinc-500">{items}</td><td className="px-5 py-4"><span className="rounded-full bg-green-50 px-2.5 py-1 text-xs font-semibold text-green-700">{payment}</span></td><td className="px-5 py-4"><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${delivery==="Delivered"?"bg-emerald-50 text-emerald-700":delivery==="Processing"?"bg-amber-50 text-amber-700":"bg-orange-50 text-orange-700"}`}>{delivery}</span></td><td className="px-5 py-4 font-bold">{amount}</td><td className="px-5 py-4"><Ellipsis className="text-zinc-400" size={18}/></td></tr>)}</tbody></table></div></article>}
function LowStock(){return <article className="rounded-3xl border border-app-border/70 bg-white p-5 shadow-sm sm:p-6"><span className="inline-flex items-center gap-1 rounded-full bg-rose-50 px-2 py-1 text-[10px] font-bold uppercase tracking-wide text-rose-600"><Zap size={11}/>4 urgent</span><h3 className="mt-3 text-lg font-bold">Low stock alerts</h3><p className="text-sm text-zinc-500">Restock before they run out</p><div className="mt-5 space-y-4">{stock.map(([name,category,count,progress,emoji])=><div key={name}><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-orange-50 text-lg">{emoji}</span><div className="min-w-0 flex-1"><div className="flex justify-between text-sm"><b>{name}</b><b className="text-rose-500">{count}</b></div><p className="text-xs text-zinc-400">{category}</p></div></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-rose-50"><i style={{width:`${progress}%`}} className="block h-full rounded-full bg-gradient-to-r from-app-orange to-rose-400"/></div></div>)}</div><button className="mt-5 w-full rounded-xl border border-app-green/15 py-2.5 text-sm font-bold text-app-green hover:bg-app-green hover:text-white">Review restock list</button></article>}
