function GenericAdminPage(){const location=useLocation();const label=useMemo(()=>navigation.find(([path])=>path===location.pathname)?.[1]||"Workspace",[location.pathname]);const endpoint=pageEndpoints[location.pathname];const[rows,setRows]=useState<Record<string,unknown>[]>([]);const[query,setQuery]=useState("");const[loading,setLoading]=useState(Boolean(endpoint));const[error,setError]=useState("");useEffect(()=>{if(!endpoint){setRows([]);setLoading(false);return;}setLoading(true);setError("");api.get(endpoint).then(({data})=>{const list=Array.isArray(data)?data:Array.isArray(data.orders)?data.orders:[];setRows(list);}).catch((err)=>setError(errorMessage(err,"Unable to load this workspace."))).finally(()=>setLoading(false));},[endpoint]);const columns=rows.length?Object.keys(rows[0]).slice(0,6):[];const visible=rows.filter(row=>JSON.stringify(row).toLowerCase().includes(query.toLowerCase()));return <section className="animate-fade-in"><div className="rounded-3xl border border-app-border/70 bg-white p-6 shadow-sm"><span className="rounded-full bg-orange-50 px-3 py-1 text-xs font-bold text-app-orange">ADMIN WORKSPACE</span><h2 className="mt-4 font-serif text-4xl">{label}</h2><p className="mt-2 max-w-lg text-zinc-500">Live data is loaded securely through the Grocers gateway.</p>{loading?<div className="mt-8 space-y-3">{[1,2,3,4].map(i=><div key={i} className="h-14 animate-pulse rounded-xl bg-app-cream"/>)}</div>:error?<div className="mt-8 rounded-2xl border border-rose-100 bg-rose-50 p-4 text-sm text-rose-700">{error}</div>:<><div className="mt-6 max-w-md"><PageSearch value={query} onChange={setQuery}/></div>{visible.length?<div className="mt-4 overflow-x-auto rounded-2xl border border-app-border"><table className="min-w-full text-left text-sm"><thead className="bg-app-cream text-xs uppercase tracking-wide text-zinc-500"><tr>{columns.map(column=><th key={column} className="px-4 py-3 font-semibold">{column.replace(/([A-Z])/g," $1")}</th>)}</tr></thead><tbody>{visible.map((row,index)=><tr key={String(row.id??index)} className="border-t border-app-border/60 hover:bg-orange-50/30">{columns.map(column=><td key={column} className="max-w-52 truncate px-4 py-3">{String(row[column]??"—")}</td>)}</tr>)}</tbody></table></div>:<div className="mt-4 rounded-2xl bg-app-cream p-8 text-center"><Package className="mx-auto text-app-orange" size={28}/><b className="mt-3 block">No matching records</b></div>}</>}</div></section>}
export function EmployeeManagementPage(){const[employees,setEmployees]=useState<Record<string,unknown>[]>([]);const[query,setQuery]=useState("");const[form,setForm]=useState({firstName:"",lastName:"",email:""});const[loading,setLoading]=useState(true);const[submitting,setSubmitting]=useState(false);const[message,setMessage]=useState("");const[error,setError]=useState("");const load=()=>{setLoading(true);api.get("/admin/employees").then(({data})=>setEmployees(Array.isArray(data)?data:[])).catch((err)=>setError(errorMessage(err,"Unable to load employees."))).finally(()=>setLoading(false));};useEffect(()=>{load();},[]);const submit=(event:React.FormEvent)=>{event.preventDefault();setSubmitting(true);setMessage("");setError("");api.post("/admin/employees",form).then(()=>{setForm({firstName:"",lastName:"",email:""});setMessage("Employee created. Their temporary password is welcome123 and they must change it on first sign-in.");load();}).catch((err)=>setError(errorMessage(err,"Unable to create employee."))).finally(()=>setSubmitting(false));};const status=(id:unknown,next:"activate"|"deactivate")=>api.post(`/admin/employees/${id}/${next}`).then(load).catch(err=>setError(errorMessage(err,`Unable to ${next} employee.`)));const visible=employees.filter(e=>JSON.stringify(e).toLowerCase().includes(query.toLowerCase()));return <section className="animate-fade-in space-y-6"><div><span className="rounded-full bg-orange-50 px-3 py-1 text-xs font-bold text-app-orange">EMPLOYEE MANAGEMENT</span><h2 className="mt-4 font-serif text-4xl">Employees</h2><p className="mt-2 text-zinc-500">Create and manage the team that keeps every grocery order moving.</p></div><div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)]"><form onSubmit={submit} className="rounded-3xl border border-app-border/70 bg-white p-6 shadow-sm"><div className="flex items-center gap-3"><span className="grid size-11 place-items-center rounded-2xl bg-orange-100 text-app-orange"><CirclePlus size={21}/></span><div><h3 className="font-bold">Add employee</h3><p className="text-sm text-zinc-500">A secure account will be created.</p></div></div><div className="mt-6 grid gap-4"><label className="text-sm font-semibold">First name<input required value={form.firstName} onChange={e=>setForm({...form,firstName:e.target.value})} className="mt-1.5 w-full rounded-xl border border-app-border bg-app-cream/40 p-3 font-normal"/></label><label className="text-sm font-semibold">Last name<input required value={form.lastName} onChange={e=>setForm({...form,lastName:e.target.value})} className="mt-1.5 w-full rounded-xl border border-app-border bg-app-cream/40 p-3 font-normal"/></label><label className="text-sm font-semibold">Email address<input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} className="mt-1.5 w-full rounded-xl border border-app-border bg-app-cream/40 p-3 font-normal"/></label></div><button disabled={submitting} className="mt-6 w-full rounded-xl bg-app-green py-3 font-semibold text-white">{submitting?"Creating employee…":"Create employee"}</button>{message&&<p className="mt-4 rounded-xl bg-green-50 p-3 text-sm text-green-700">{message}</p>}{error&&<p className="mt-4 rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}</form><article className="overflow-hidden rounded-3xl border border-app-border/70 bg-white shadow-sm"><div className="flex items-center justify-between p-6"><div><h3 className="font-bold">Your employees</h3><p className="text-sm text-zinc-500">{employees.length} team members</p></div><input value={query} onChange={e=>setQuery(e.target.value)} className="w-40 rounded-xl border p-2 text-sm" placeholder="Search"/></div>{loading?<div className="space-y-3 p-6 pt-0">{[1,2,3].map(i=><div key={i} className="h-14 animate-pulse rounded-xl bg-app-cream"/>)}</div>:<div className="overflow-x-auto"><table className="min-w-full text-left text-sm"><thead className="bg-app-cream text-xs uppercase tracking-wide text-zinc-500"><tr><th className="px-5 py-3">Employee</th><th className="px-5 py-3">Email</th><th className="px-5 py-3">Status</th><th className="px-5 py-3"></th></tr></thead><tbody>{visible.map((employee,index)=><tr key={String(employee.id??index)} className="border-t border-app-border/60"><td className="px-5 py-4 font-semibold">{String(employee.firstName??"")} {String(employee.lastName??"")}</td><td className="px-5 py-4 text-zinc-500">{String(employee.email??"—")}</td><td className="px-5 py-4">{String(employee.status??"ACTIVE")}</td><td className="px-5 py-4"><button onClick={()=>status(employee.id,employee.status==="INACTIVE"?"activate":"deactivate")} className="text-xs font-bold text-app-orange">{employee.status==="INACTIVE"?"Activate":"Deactivate"}</button></td></tr>)}</tbody></table></div>}</article></div></section>}
